        <span className="h-[2px] flex-1 bg-brand-ink/15" />
        or with email
        <span className="h-[2px] flex-1 bg-brand-ink/15" />
      </div>

      {/* Email OTP / magic link */}
      <form action={action} className="flex flex-col gap-3">
        <label htmlFor="email" className="font-display text-lg uppercase tracking-wide">
          Email
        </label>
        <input
          id="email"
          name="email"
          type="email"
          required
